async function countryJobCommand(request,action){await director(request);const country=countryJobs.country(request.data?.country),ref=db.collection('course_country_ingestion_jobs').doc(countryJobs.jobId(country)),requestId=crypto.randomUUID();if(country==='UNKNOWN')throw new HttpsError('failed-precondition','COUNTRY_UNKNOWN');const snapshot=await ref.get(),existing=snapshot.exists?snapshot.data():null;if(action==='start'){if(request.data?.confirmed!==true)throw new HttpsError('failed-precondition','EXPLICIT_COUNTRY_START_APPROVAL_REQUIRED');const job=countryJobs.start(existing,{country});if(!job.idempotent)await ref.set({...job,schema:'golfriend.country-ingestion-job.v1',createdAt:stamp(),updatedAt:stamp(),createdBy:request.auth.uid,createdAction:'DIRECTOR_START_COUNTRY',explicitApproval:true,requestId});return job;}if(!existing)throw new HttpsError('not-found','COUNTRY_JOB_NOT_FOUND');const resumed=action==='resume',state=resumed?'queued':'paused';await ref.set({state,pauseReason:resumed?null:'ADMIN_PAUSED',retryAtMs:resumed?null:existing.retryAtMs??null,nextDueAtMs:resumed?Date.now():existing.nextDueAtMs??null,updatedAt:stamp(),lastAction:resumed?'DIRECTOR_RESUME_COUNTRY':'DIRECTOR_PAUSE_COUNTRY',lastActionBy:request.auth.uid,lastActionRequestId:requestId},{merge:true});return{jobId:ref.id,country,state,providerCalls:0,courseWrites:0};}
