exports.scheduledCourseCountryIngestionWorker=onSchedule({region:REGION,schedule:'every 5 minutes',timeZone:'Asia/Bangkok',secrets:[key],memory:'1GiB',timeoutSeconds:120,maxInstances:1,retryCount:0},async()=>{const activation=await verifyActivation(await configuration());if(!activation.allowed)return{state:'blocked',reason:activation.reason,providerCalls:0,courseWrites:0};const enrollment=await advanceCountryRefreshEnrollment();if(enrollment.state==='enrolling')return enrollment;const claim=await claimCountryJob();if(!claim)return{state:enrollment.state==='complete'?'idle':enrollment.state,providerCalls:0,courseWrites:0};const result=await countryWorker.runOne({job:claim.job,provider:async()=>{const endpoint=`${FIRST}&country=${encodeURIComponent(claim.job.country)}`,response=await provider(endpoint,key.value(),d.createLimiter(),.1,claim.job.jobId);if(response.deferred)return response;const decoded=d.validatePage(response.body);if(!decoded.valid)throw Error(decoded.reason);return{courses:decoded.clubs,quarantine:decoded.quarantine,body:response.body,retrievedAt:response.retrievedAt,reservationId:response.reservationId,requestEvidence:{endpoint,requestIdentity:response.reservationId,httpStatus:response.httpStatus,responseDigest:response.responseDigest,providerRemaining:response.providerRemaining,cost:response.measuredCost,reservedCost:response.reservedCost,cursorBefore:null,cursorAfter:null,normalizedCandidateCount:decoded.clubs.reduce((count,club)=>count+(club.courses||[]).length,0),safeSampleCourseIds:decoded.clubs.flatMap(club=>(club.courses||[]).map(course=>course.courseID)).slice(0,5)}};},persist:(countryJob,rows,response)=>processMapping({countryJob,rows,response})});if(result.requestEvidence?.safeSampleCourseIds)result.storedCourseIds=result.requestEvidence.safeSampleCourseIds;return recordCountryWorkerResult(claim,result);});
